package TOPSECRET.dto.city.request;

import jakarta.validation.ConstraintViolation;
import jakarta.validation.Validation;
import jakarta.validation.Validator;
import jakarta.validation.ValidatorFactory;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

import java.util.Set;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for {@link RequestCityDTO}.
 *
 * <p>Verifies that Bean Validation constraints are correctly declared
 * on all fields. Getter, equality, hash code, and string representation
 * are generated by the record and are not tested here.</p>
 */
class RequestCityDTOTest {

    private static Validator validator;

    @BeforeAll
    static void setUp() {
        ValidatorFactory factory = Validation.buildDefaultValidatorFactory();
        validator = factory.getValidator();
    }

    @Test
    void cityName_ShouldFailValidation_WhenBlank() {
        // ARRANGE
        RequestCityDTO dto = new RequestCityDTO("", "PT");

        // ACT
        Set<ConstraintViolation<RequestCityDTO>> violations = validator.validate(dto);

        // ASSERT
        assertFalse(violations.isEmpty());
        assertTrue(violations.stream()
                .anyMatch(v -> v.getPropertyPath().toString().equals("cityName")));
    }

    @Test
    void countryId_ShouldFailValidation_WhenBlank() {
        // ARRANGE
        RequestCityDTO dto = new RequestCityDTO("Porto", "");

        // ACT
        Set<ConstraintViolation<RequestCityDTO>> violations = validator.validate(dto);

        // ASSERT
        assertFalse(violations.isEmpty());
        assertTrue(violations.stream()
                .anyMatch(v -> v.getPropertyPath().toString().equals("countryId")));
    }

    @Test
    void dto_ShouldPassValidation_WhenAllFieldsAreValid() {
        // ARRANGE
        RequestCityDTO dto = new RequestCityDTO("Porto", "PT");

        // ACT
        Set<ConstraintViolation<RequestCityDTO>> violations = validator.validate(dto);

        // ASSERT
        assertTrue(violations.isEmpty());
    }
}